changeSet.sql:
-- Remove the retired provider without relabelling its observations as BenzUp data.
UPDATE regional_price_keys SET current_observation_id = NULL WHERE provider_code = 'WHEREFUEL';
DELETE FROM regional_price_observations
WHERE price_key_id IN (SELECT id FROM regional_price_keys WHERE provider_code = 'WHEREFUEL');
DELETE FROM regional_price_keys WHERE provider_code = 'WHEREFUEL';
DELETE FROM source_publications
WHERE feed_id IN (SELECT id FROM source_feeds WHERE provider_code = 'WHEREFUEL');

DELETE FROM import_runs WHERE feed_id IN (SELECT id FROM source_feeds WHERE provider_code = 'WHEREFUEL');
DELETE FROM source_fetch_states WHERE feed_id IN (SELECT id FROM source_feeds WHERE provider_code = 'WHEREFUEL');
DELETE FROM source_feeds WHERE provider_code = 'WHEREFUEL';
DELETE FROM data_sources WHERE code = 'WHEREFUEL';

ALTER TABLE source_feeds DROP CONSTRAINT source_feeds_ck1, DROP CONSTRAINT source_feeds_ck2;
ALTER TABLE source_feeds ADD CONSTRAINT source_feeds_ck1 CHECK (
    frequency IN ('DAILY', 'WEEKLY', 'MONTHLY')
    AND aggregation_method IN ('OFFICIAL_STATISTICS', 'REGIONAL_INDEX_MEAN')
    AND update_status IN ('READY', 'DELAYED', 'UNAVAILABLE', 'UNKNOWN')
);
ALTER TABLE source_feeds ADD CONSTRAINT source_feeds_ck2 CHECK (
    (aggregation_method = 'OFFICIAL_STATISTICS' AND sampling_policy_code IS NULL)
    OR (aggregation_method = 'REGIONAL_INDEX_MEAN' AND sampling_policy_code IS NOT NULL AND length(trim(sampling_policy_code)) > 0)
);
ALTER TABLE regional_price_keys DROP CONSTRAINT regional_price_keys_ck1;
ALTER TABLE regional_price_keys ADD CONSTRAINT regional_price_keys_ck1
    CHECK (provider_code IN ('ROSSTAT', 'RUSTATA', 'BENZUP'));
ALTER TABLE price_periods DROP CONSTRAINT price_periods_ck1, DROP CONSTRAINT price_periods_ck2;
ALTER TABLE price_periods ADD CONSTRAINT price_periods_ck1 CHECK (
    basis = 'REGIONAL_CONSUMER_AVERAGE' AND frequency IN ('DAILY', 'WEEKLY', 'MONTHLY')
);
ALTER TABLE price_periods ADD CONSTRAINT price_periods_ck2 CHECK (
    (frequency = 'DAILY' AND start_date = reference_date AND end_date = reference_date
        AND start_date IS NOT NULL AND end_date IS NOT NULL)
    OR (frequency = 'WEEKLY' AND (
        (start_date IS NULL AND end_date IS NULL)
        OR (start_date IS NOT NULL AND end_date IS NOT NULL AND start_date <= reference_date AND reference_date <= end_date)))
    OR (frequency = 'MONTHLY' AND start_date IS NOT NULL AND end_date IS NOT NULL
        AND start_date = date_trunc('month', start_date::timestamp)::date
        AND end_date = (start_date + INTERVAL '1 month - 1 day')::date AND reference_date = end_date)
);
ALTER TABLE regional_price_observations DROP CONSTRAINT regional_price_observations_ck2;
